  const [bannerIdx, setBannerIdx] = useState(0);
  useEffect(() => { const t = setInterval(() => setBannerIdx(i => (i + 1) % BANNERS.length), 5000); return () => clearInterval(t); }, []);
  const [editingNl, setEditingNl] = useState(false);
  const [editNlTitle, setEditNlTitle] = useState("");
  const [editNlBody, setEditNlBody] = useState("");
  const [editingBoard, setEditingBoard] = useState(false);
  const [editBoardTitle, setEditBoardTitle] = useState("");
  const [editBoardBody, setEditBoardBody] = useState("");
  const [emailSubject, setEmailSubject] = useState("");
  const [emailBody, setEmailBody] = useState("");
  const [emailFiles, setEmailFiles] = useState([]);
  const [emailSent, setEmailSent] = useState(false);
  const emailRef = useRef();
  const inputRef = useRef();
  const t = i18n[lang];
  const isAdmin = account && account.role === "admin";
  const isLoggedIn = !!account;

  // Firebase: Load data
  const loadNewsletters = async () => {
    try {
      const q = query(collection(db, "newsletters"), orderBy("createdAt", "desc"));
      const snap = await getDocs(q);
      setItems(snap.docs.map(d => ({ ...d.data(), id: d.id })));
    } catch(e) { console.error("Load newsletters error:", e); }
  };

  const loadBoardPosts = async () => {
    try {
      const q = query(collection(db, "boardPosts"), orderBy("createdAt", "desc"));
      const snap = await getDocs(q);
      const posts = [];
      for (const d of snap.docs) {
        const post = { ...d.data(), id: d.id };
        const cq = query(collection(db, "boardPosts", d.id, "comments"), orderBy("createdAt", "asc"));
        const csnap = await getDocs(cq);
        post.comments = csnap.docs.map(c => ({ ...c.data(), id: c.id }));
        posts.push(post);
      }
      setBoardPosts(posts);
    } catch(e) { console.error("Load board error:", e); }
  };

  useEffect(() => { loadNewsletters(); loadBoardPosts(); }, []);

  const saveNewsletter = async (data) => {
    try {
      await addDoc(collection(db, "newsletters"), { ...data, createdAt: serverTimestamp() });
      loadNewsletters();
    } catch(e) { console.error("Save newsletter error:", e); }
  };

  const deleteNewsletter = async (id) => {
    try {
      await deleteDoc(doc(db, "newsletters", id));
      loadNewsletters();
    } catch(e) { console.error("Delete newsletter error:", e); }
  };

  const saveBoardPost = async (data) => {
    try {
      await addDoc(collection(db, "boardPosts"), { ...data, createdAt: serverTimestamp() });
      loadBoardPosts();
    } catch(e) { console.error("Save board post error:", e); }
  };

