                        await saveNewsletter({ title: nlTitle, summary: nlSummary || nlTitle, content: `<h2>${nlTitle}</h2>${html}`, author: account.name, cover: "📝", type: "POST", size: "-", date: new Date().toISOString().slice(0, 10) });
